import { chromium } from 'playwright';
import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import path from 'path';

const dir = '/workspace/sandbox/skills/building-accessible-ui/modal-dialog--framework-react--style-modern/claude-sonnet-4.6__s3';
const html = readFileSync(path.join(dir, 'index.html'), 'utf8');

const browser = await chromium.launch();
const page = await browser.newPage();

// Intercept CSS/JS so relative paths resolve
await page.route('**/styles.css', r => r.fulfill({ path: path.join(dir, 'styles.css') }));
await page.route('**/script.js',  r => r.fulfill({ path: path.join(dir, 'script.js') }));

